def docx_text(path):
    doc=Document(path)
    parts=[]
    for p in doc.paragraphs:
        t=p.text.strip()
        if t:
            parts.append(t)
    for table in doc.tables:
        for row in table.rows:
            row_text=' | '.join(cell.text.strip().replace('\n',' / ') for cell in row.cells if cell.text.strip())
            if row_text:
                parts.append(row_text)
    return '\n'.join(parts)

def pptx_text(path):
    out=[]
    with ZipFile(path) as z:
        slides=sorted([n for n in z.namelist() if re.match(r'ppt/slides/slide\d+\.xml$', n)], key=lambda n:int(re.search(r'(\d+)', n).group(1)))
        for slide in slides:
            root=ET.fromstring(z.read(slide))
            texts=[]
            for el in root.iter():
                if el.tag.endswith('}t') and el.text:
